-- ----------------------------
-- Table structure for sch_calendar_detail
-- ----------------------------
DROP TABLE IF EXISTS `sch_calendar_detail`;
CREATE TABLE `sch_calendar_detail` (
  `CODE_` varchar(64) NOT NULL COMMENT '日历编码',
  `NAME_` varchar(256) DEFAULT NULL COMMENT '日历名称',
  `WEEKLY_` varchar(64) DEFAULT NULL COMMENT '是否包含周末:\r\n            Y - 包含\r\n            N - 不包含',
  `TIME_INTERVAL_` varchar(2000) DEFAULT NULL COMMENT '排除时段设置',
  `REMARK_` varchar(512) DEFAULT NULL COMMENT '备注',
  `TENANT_ID_` varchar(64) DEFAULT NULL COMMENT '租户',
  `CREATED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '创建人ID',
  `CREATED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '创建人名称',
  `CREATED_TIME_` datetime DEFAULT NULL COMMENT '创建时间',
  `DELFLAG_` varchar(1) DEFAULT NULL COMMENT '逻辑删除标记',
  `DISPLAY_ORDER_` int(11) DEFAULT NULL COMMENT '显示序号',
  `MODIFIED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '修改人ID',
  `MODIFIED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '修改人名称',
  `MODIFIED_TIME_` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `VERSION_` int(11) DEFAULT NULL COMMENT '版本',
  PRIMARY KEY (`CODE_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='集群管理';

-- ----------------------------
-- Records of sch_calendar_detail
-- ----------------------------

-- ----------------------------
-- Table structure for sch_cluster
-- ----------------------------
DROP TABLE IF EXISTS `sch_cluster`;
CREATE TABLE `sch_cluster` (
  `CODE_` varchar(64) NOT NULL COMMENT '服务器编码',
  `NAME_` varchar(256) DEFAULT NULL COMMENT '服务器名称',
  `REMARK_` varchar(512) DEFAULT NULL COMMENT '备注',
  `TENANT_ID_` varchar(64) DEFAULT NULL COMMENT '租户',
  `CREATED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '创建人ID',
  `CREATED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '创建人名称',
  `CREATED_TIME_` datetime DEFAULT NULL COMMENT '创建时间',
  `DELFLAG_` varchar(1) DEFAULT NULL COMMENT '逻辑删除标记',
  `DISPLAY_ORDER_` int(11) DEFAULT NULL COMMENT '显示序号',
  `MODIFIED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '修改人ID',
  `MODIFIED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '修改人名称',
  `MODIFIED_TIME_` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `VERSION_` int(11) DEFAULT NULL COMMENT '版本',
  PRIMARY KEY (`CODE_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='集群管理';

