DROP TABLE IF EXISTS `sch_job_inst`;
CREATE TABLE `sch_job_inst` (
  `ID_` varchar(64) NOT NULL COMMENT 'ID',
  `JOB_CODE_` varchar(64) DEFAULT NULL COMMENT '任务编码',
  `JOB_NAME_` varchar(256) DEFAULT NULL COMMENT '任务名称',
  `GROUP_CODE_` varchar(64) DEFAULT NULL COMMENT '任务类型',
  `PARAM_` varchar(2000) DEFAULT NULL COMMENT '任务参数:JSON字符串。',
  `NODE_CODE_` varchar(64) DEFAULT NULL COMMENT '节点编码',
  `CLUSTER_CODE_` varchar(64) DEFAULT NULL COMMENT '集群编码',
  `START_TIME` datetime DEFAULT NULL COMMENT '开始时间',
  `END_TIME` datetime DEFAULT NULL COMMENT '结束时间',
  `EXEC_TIME_` bigint(20) DEFAULT NULL COMMENT '执行时间',
  `STATUS_` varchar(64) DEFAULT NULL COMMENT '状态:\r\n            NEW - 新建\r\n            NOTIFYING - 通知中\r\n            EXECUTING  执行中\r\n            DONE - 执行完成\r\n            ERROR - 执行失败',
  `TIMEOUT_TIMES_` int(11) DEFAULT NULL COMMENT '超时次数',
  `ERROR_TIMES_` int(11) DEFAULT NULL COMMENT '错误次数',
  `ERROR_MESSAGE_` varchar(500) DEFAULT NULL COMMENT '错误原因',
  `RECOVERED_` varchar(64) DEFAULT NULL COMMENT '是否恢复',
  `TRIGGER_KEY_` varchar(256) DEFAULT NULL COMMENT '触发器',
  `LAST_TRIGGER_KEY_` varchar(256) DEFAULT NULL COMMENT '上次触发器',
  `SCHEDULED_FIRE_TIME_` bigint(20) DEFAULT NULL COMMENT '计划触发时间',
  `SERVER_INSTANCE_ID_` varchar(64) DEFAULT NULL COMMENT '实例ID',
  `TENANT_ID_` varchar(64) DEFAULT NULL COMMENT '租户',
  `CREATED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '创建人ID',
  `CREATED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '创建人名称',
  `CREATED_TIME_` datetime DEFAULT NULL COMMENT '创建时间',
  `DELFLAG_` varchar(1) DEFAULT NULL COMMENT '逻辑删除标记',
  `DISPLAY_ORDER_` int(11) DEFAULT NULL COMMENT '显示序号',
  `MODIFIED_BY_ID_` varchar(64) DEFAULT NULL COMMENT '修改人ID',
  `MODIFIED_BY_NAME_` varchar(64) DEFAULT NULL COMMENT '修改人名称',
  `MODIFIED_TIME_` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `VERSION_` int(11) DEFAULT NULL COMMENT '版本',
  PRIMARY KEY (`ID_`),
  KEY `FK_Reference_6_SCH_JEP` (`JOB_CODE_`),
  CONSTRAINT `FK_Reference_6_SCH_JEP` FOREIGN KEY (`JOB_CODE_`) REFERENCES `sch_job_entity` (`CODE_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='调度任务实例';

