  CONSTRAINT `FK_DATA_PROVIDER` FOREIGN KEY (`PROVIDER_CODE_`) REFERENCES `sys_data_provider` (`QUERY_ID_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='组件所包含的数据提供程序，可能有多个。';

