  KEY `FK_Reference_1` (`ROLE_STD_CODE_`),
  CONSTRAINT `sys_role_ibfk_1` FOREIGN KEY (`ROLE_STD_CODE_`) REFERENCES `sys_role_std` (`ROLE_STD_CODE_`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='系统角色表';

